q=A.Y(new A.aM(A.b([A.a4(["title","C\u1ed9t M\u1ed1c 36.000 Bi\u1ebfn & \u0110\xe0i Sen N\xe2ng \u0110\u1ee1","meta",s,"preview","Khi m\u1ed9t h\xe0nh gi\u1ea3 ch\xed t\xe2m tr\xec t\u1ee5ng \u0111\u1ea1t t\u1edbi c\u1ed9t m\u1ed1c t\u1ed1i th\u01b0\u1ee3ng 36.000 bi\u1ebfn, nh\u1eefng ph\xe9p m\u1ea7u hi\u1ec7n ti\u1ec1n s\u1ebd h\xf3a sinh. T\xedch l\u0169y \u0111\u1ee7 36.000 l\u1ea7n m\u1ed9t c\xe1ch chu\u1ea9n x\xe1c, m\u1ed9t hi\u1ec7n t\u01b0\u1ee3ng vi di\u1ec7u s\u1ebd xu\u1ea5t hi\u1ec7n: d\u01b0\u1edbi th\xe2n ng\u01b0\u1eddi \u0111\xf3 s\u1ebd hi\u1ec7n ra m\u1ed9t \u0111\xe0i sen n\xe2ng \u0111\u1ee1 trong kho\u1ea3ng kh\xf4ng v\xf4 h\xecnh."],q,q),A.a4(["title","\u0110\u1ecbnh Qu\u1ed1c V\xe3ng Sinh \u2014 36.000 \u0110\u1ea1o H\xe0o Quang","meta",s,"preview","M\u1ed7i bi\u1ebfn Ch\xfa L\u0103ng Nghi\xeam \u0111\u01b0\u1ee3c t\u1ee5ng l\xean gi\u1ed1ng nh\u01b0 vi\u1ec7c v\u1ebd m\u1ed9t \u0111\u1ea1o h\xe0o quang r\u1ef1c r\u1ee1 bao b\u1ecdc xung quanh c\u01a1 th\u1ec3. Do \u0111\xf3, khi t\u1ee5ng \u0111\u1ee7 36.000 bi\u1ebfn, th\xe2n t\xe2m h\xe0nh gi\u1ea3 s\u1ebd c\xf3 36.000 \u0111\u1ea1o h\xe0o quang ki\xean c\u1ed1 b\u1ea3o v\u1ec7, ch\u1eafc ch\u1eafn tho\xe1t kh\u1ecfi ba \u0111\u01b0\u1eddng \xe1c nghi\u1ec7p."],q,q),A.a4(["title","C\u1ee9u \u0110\u1ed9 Cha M\u1eb9 Trong B\u1ea3y \u0110\u1eddi Nhi\u1ec1u Ki\u1ebfp","meta",s,"preview","N\u0103ng l\u1ef1c c\u1ee7a 36.000 bi\u1ebfn t\u1ee5ng kh\xf4ng ch\u1ec9 \u0111em l\u1ea1i s\u1ef1 th\xe0nh t\u1ef1u ri\xeang cho b\u1ea3n th\xe2n, m\xe0 c\xf2n t\u1ecfa n\u0103ng l\u01b0\u1ee3ng c\u1ee9u \u0111\u1ed9 to l\u1edbn. C\xf4ng \u0111\u1ee9c th\xf9 th\u1eafng n\xe0y c\xf3 th\u1ec3 gi\xfap c\u1ee9u \u0111\u1ed9 cha m\u1eb9 trong b\u1ea3y \u0111\u1eddi, th\u1eadm ch\xed l\xe0 cha m\u1eb9 trong nhi\u1ec1u ki\u1ebfp qu\xe1 kh\u1ee9 \u0111\u1ec1u \u0111\u01b0\u1ee3c gi\u1ea3i tho\xe1t si\xeau sinh."],q,q),A.a4(["title","S\u1ef1 T\u1ed3n Vong C\u1ee7a Ch\xe1nh Ph\xe1p","meta",r,"preview","Ch\xfa L\u0103ng Nghi\xeam l\xe0 linh v\u0103n c\u1ee9u m\u1ea1ng c\u1ee7a tr\u1eddi \u0111\u1ea5t. B\u1ea5t c\u1ee9 l\xfac n\xe0o c\u0169ng ph\u1ea3i c\xf3 ng\u01b0\u1eddi tr\xec t\u1ee5ng Ch\xfa L\u0103ng Nghi\xeam \u0111\u1ec3 ch\u1ed1ng \u0111\u1ee1 tr\u1eddi \u0111\u1ea5t, kh\xf4ng \u0111\u1ec3 cho th\u1ebf gi\u1edbi \u0111i \u0111\u1ebfn ch\u1ed7 ho\u1ea1i di\u1ec7t. N\u1ebfu kh\xf4ng c\xf2n ai t\u1ee5ng Ch\xfa L\u0103ng Nghi\xeam n\u1eefa, th\u1ebf gi\u1edbi n\xe0y s\u1ebd nhanh ch\xf3ng \u0111i \u0111\u1ebfn c\xf5i di\u1ec7t."],q,q),A.a4(["title","C\u1ea3nh Gi\u1edbi Th\xe2n Kim Cang B\u1ea5t Ho\u1ea1i","meta",s,"preview","Qu\xe1 tr\xecnh tinh t\u1ea5n tr\xec t\u1ee5ng \u0111\u1ea1i th\u1ea7n ch\xfa gi\xfap tr\u01b0\u1ee3c kh\xed gi\u1ea3m s\xe2u, thanh kh\xed th\u0103ng ti\u1ebfn, chuy\u1ec3n h\xf3a ph\xe0m th\xe2n th\xe0nh Th\xe2n Kim Cang. C\u01a1 th\u1ec3 tr\u1edf n\xean c\u1ee9ng ch\u1eafc nh\u01b0 \u0111\u1ed3ng s\u1eaft, h\xe0m r\u0103ng 36 chi\u1ebfc t\u1ef1 m\u1ecdc l\u1ea1i, v\xe0 th\xe2n th\u1ec3 t\u1ef1 t\u1ecfa m\xf9i h\u01b0\u01a1ng \u0111\xe0n h\u01b0\u01a1ng n\u1ed3ng n\xe0n b\u1ea5t bi\u1ebfn."],q,q),A.a4(["title","B\xe1ch \u0110\u1ed9c B\u1ea5t S\xe2m & Th\u1ea7n Th\xf4ng Mu\xf4ng Th\xfa","meta",s,"preview","Th\xe2n th\u1ec3 mi\u1ec5n nhi\u1ec5m ho\xe0n to\xe0n v\u1edbi t\u1ea5t c\u1ea3 b\u1ec7nh t\u1eadt, \u0111\u1ed9c ch\u1ea5t. \u0110\u1eb7c bi\u1ec7t, khi h\xe0nh gi\u1ea3 tr\xec t\u1ee5ng v\u01b0\u1ee3t qua m\u1ed1c 1.000.000 bi\u1ebfn, h\u1ecd s\u1ebd \u0111\u1eafc \u0111\u01b0\u1ee3c kh\u1ea3 n\u0103ng th\u1ea5u hi\u1ec3u ng\xf4n ng\u1eef c\u1ee7a mu\xf4n lo\xe0i \u0111\u1ed9ng v\u1eadt, tho\xe1t kh\u1ecfi th\u1ebf gi\u1edbi h\u01b0 \u1ea3o huy\u1ec5n c\u1ea3nh."],q,q),A.a4(["title","V\xec Sao Tr\xec L\u0103ng Nghi\xeam Ch\xfa Ph\u1ea3i Ni\u1ec7m L\u1edbn Ti\u1ebfng","meta",s,"preview","Ph\xe0m l\xe0 ng\u01b0\u1eddi \u0111\u1ebfn Quan \xc2m C\u1ed5 \u0110\u1ed9ng tu h\xe0nh th\xec nh\u1ea5t \u0111\u1ecbnh ph\u1ea3i ni\u1ec7m l\u1edbn ti\u1ebfng. V\xec sao th\u1ea7y k\xeau c\xe1c Ph\u1eadt t\u1eed ni\u1ec7m l\u1edbn ti\u1ebfng? Ni\u1ec7m l\u1edbn ti\u1ebfng L\u0103ng Nghi\xeam Ch\xfa, th\xec hoa sen c\u1ee7a c\xe1c Ph\u1eadt t\u1eed c\u0169ng l\u1edbn theo. Ni\u1ec7m cho t\u1ed1t th\xec cha m\u1eb9 \u0111\u1ec1u \u0111\u01b0\u1ee3c l\u1ee3i \xedch, \u0111\u1ec1u \u0111\u01b0\u1ee3c ng\u1ed3i tr\xean hoa sen. C\xe1c Ph\u1eadt t\u1eed xem Th\xedch Ca M\xe2u Ni Ph\u1eadt, D\u01b0\u1ee3c S\u01b0 Ph\u1eadt, A Di \u0110\xe0 Ph\u1eadt trong \u0110\u1ea1i H\xf9ng B\u1ea3o \u0110i\u1ec7n, c\xe1c Ng\xe0i \u0111\u1ec1u ng\u1ed3i tr\xean hoa sen 5 t\u1ea7ng.\n\nNi\u1ec7m l\u1edbn ti\u1ebfng L\u0103ng Nghi\xeam Ch\xfa kh\xf4ng ch\u1ec9 c\xf3 l\u1ee3i cho b\u1ea3n th\xe2n. N\xf3 c\xf2n c\xf3 th\u1ec3 \u0111\u1ea3 th\xf4ng to\xe0n b\u1ed9 kinh m\u1ea1ch trong th\xe2n th\u1ec3. Ni\u1ec7m l\u1edbn ti\u1ebfng th\xec s\u1ebd kh\xf4ng c\xf2n \u0111\u1ee7 th\u1ee9 v\u1ecdng t\u01b0\u1edfng n\u1eefa.\n\nV\xec sao c\u1ea3 \u0111\u1eddi th\u1ea7y kh\xf4ng cho ph\xe9p m\u1eb7c ni\u1ec7m v\xe0 ni\u1ec7m nh\u1ecf ti\u1ebfng? Ni\u1ec7m L\u0103ng Nghi\xeam Ch\xfa ph\u1ea3i h\xe9t to ra, \xe2m thanh c\xe0ng l\u1edbn c\xe0ng t\u1ed1t. Th\u1ea7y th\xedch nh\u1ea5t l\xe0 ng\u01b0\u1eddi c\xf3 \xe2m thanh l\u1edbn. Khi h\xe9t to ra r\u1ed3i, th\xec th\xe2n v\xe0 t\xe2m c\u1ee7a Ph\u1eadt t\u1eed \u0111\u1ec1u \u1edf trong c\xe2u ch\xfa, s\u1ebd kh\xf4ng \u0111i kh\u1edfi v\u1ecdng t\u01b0\u1edfng n\u1eefa. \u0110\u1ee7 th\u1ee9 b\u1ec7nh t\u1eadt c\u0169ng kh\xf4ng c\xf2n. C\u0169ng s\u1ebd kh\xf4ng c\xf3 50 lo\u1ea1i \u1ea5m ma. \u1ea4m ma l\xe0 g\xec? Ch\xednh l\xe0 t\xe0 t\u01b0 t\xe0 ki\u1ebfn trong t\xe2m c\u1ee7a ch\xednh m\xecnh, nh\u01b0 v\u1eady l\xe0 b\u1ecb ma \xe1m r\u1ed3i.\n\nNi\u1ec7m l\u1edbn ti\u1ebfng L\u0103ng Nghi\xeam Ch\xfa, h\u1ebft th\u1ea3y ma \u0111\u1ec1u kh\xf4ng c\xf2n. Ch\xfang n\xf3 t\u1eeb xa \u0111\u1ec1u qu\u1ef3 xu\u1ed1ng d\u1eadp \u0111\u1ea7u \u0111\u1ea3nh l\u1ec5 Ph\u1eadt t\u1eed. Cho \u0111\u1ebfn nh\u1eefng con tr\xf9ng con ki\u1ebfn, t\u1ea5t c\u1ea3 ch\xfang sinh, ch\u1ec9 c\u1ea7n nghe \u0111\u01b0\u1ee3c th\xf4i, v\u1ecb lai \u0111\u1ec1u s\u1ebd th\xe0nh Ph\u1eadt.\n\nM\u1ed7i m\u1ed9t ch\u1eef m\u1ed7i m\u1ed9t c\xe2u c\u1ee7a L\u0103ng Nghi\xeam Ch\xfa \u0111\u1ec1u l\xe0 ph\xe1 \u0111\u1ecba ng\u1ee5c. Nh\u1eefng ch\xfang sinh \u0111ang ch\u1ecbu kh\u1ed5 trong \u0111\u1ecba ng\u1ee5c \u0111\u1ec1u c\xf3 th\u1ec3 \u0111\u01b0\u1ee3c \u0111\u1ed9. Cho n\xean uy l\u1ef1c c\u1ee7a L\u0103ng Nghi\xeam Ch\xfa ch\xednh l\xe0 l\u1edbn nh\u01b0 v\u1eady \u0111\xf3."],q,q),A.a4(["title","C\u1ea5u Tr\xfac Kh\u1edfi \u0110\u1ea7u C\u1ee7a B\xe0i T\u1ee5ng","meta",s,"preview",'\u0110\u1ec3 b\xe0i tr\xec ch\xfa c\xf3 hi\u1ec7u qu\u1ea3 t\u1ed1t nh\u1ea5t, tuy\u1ec7t \u0111\u1ed1i kh\xf4ng n\xean b\u1ecf qua nghi th\u1ee9c kh\u1edfi \u0111\u1ea7u: Lu\xf4n ph\u1ea3i ni\u1ec7m 3 l\u1ea7n c\xe2u "\u0110\u1ea1i Ph\u1eadt \u0110\u1ea3nh Th\u1ee7 L\u0103ng Nghi\xeam Th\u1ea7n Ch\xfa". C\xe2u n\xe0y gi\u1ed1ng nh\u01b0 c\xe1i \u0111\u1ea7u, ph\u1ea7n th\u1ea7n ch\xfa l\xe0 th\xe2n th\u1ec3; n\u1ebfu kh\xf4ng t\u1ee5ng gi\u1ed1ng nh\u01b0 c\u01a1 th\u1ec3 kh\xf4ng c\xf3 \u0111\u1ea7u.'],q,q),A.a4(["title","S\u1ef1 B\u1ea3o V\u1ec7 C\u1ee7a 8 V\u1ea1n 4 Ng\xe0n Kim Cang T\u1ea1ng","meta",r,"preview","B\u1ea1n t\u1ee5ng Ch\xfa L\u0103ng Nghi\xeam, d\xf9 b\u1ea1n ch\u1ec9 t\u1ee5ng m\u1ed9t ch\u1eef, m\u1ed9t c\xe2u, m\u1ed9t h\u1ed9i, hay to\xe0n b\u1ed9, th\xec t\xe1m v\u1ea1n b\u1ed1n ng\xe0n Kim Cang T\u1ea1ng B\u1ed3 T\xe1t c\xf9ng quy\u1ebfn thu\u1ed9c c\u1ee7a c\xe1c ng\xe0i c\u0169ng lu\xf4n lu\xf4n theo b\u1ea3o v\u1ec7 b\u1ea1n c\u1ea9n th\u1eadn, kh\xf4ng \u0111\u1ec3 cho b\u1ea5t k\u1ef3 lo\xe0i ma qu\u1ef7 n\xe0o \u0111\u1ebfn qu\u1ea5y nhi\u1ec5u."],q,q),A.a4(["title","Kh\xf4ng N\xean \u0102n Tr\u1ee9ng Khi Tr\xec Ch\xfa","meta",s,"preview","Kh\xf4ng n\xean \u0103n tr\u1ee9ng khi tr\xec t\u1ee5ng Ch\xfa L\u0103ng Nghi\xeam. Vi\u1ec7c \u0103n tr\u1ee9ng g\xe0 mang t\u1ed9i n\u1eb7ng h\u01a1n c\u1ea3 \u0103n th\u1ecbt th\xf4ng th\u01b0\u1eddng, b\u1edfi l\u1ebd m\u1ed7i qu\u1ea3 tr\u1ee9ng \u0111\u1ea1i di\u1ec7n cho m\u1ed9t sinh m\u1ea1ng nguy\xean v\u1eb9n. \u0102n tr\u1ee9ng mang m\xf9i tanh, ng\u0103n c\u1ea3n th\xe2n t\xe2m \u0111\u1ea1t \u0111\u1ebfn thu\u1ea7n t\u1ecbnh L\u0103ng Nghi\xeam Tam Mu\u1ed9i."],q,q),A.a4(["title","B\u1ea3o Ph\xe1p Ng\u0169 \u0110\u1ea1i T\xe2m Ch\xfa Cho Ng\u01b0\u1eddi B\u1eadn R\u1ed9n","meta",s,"preview","N\u1ebfu kh\xf4ng \u0111\u1ee7 th\u1eddi gian tr\xec to\xe0n b\u1ed9, h\xe3y t\u1ee5ng Ng\u0169 \u0110\u1ea1i T\xe2m Ch\xfa: S\u1ea4T \u0110\xc0N N\u1ec2 \u2014 A CA GIA \u2014 M\u1eacT R\u1eca TR\u1ee4 \u2014 B\xc1T R\u1eca \u0110\xc1T RA GIA \u2014 N\u1ea2NH Y\u1ebeT R\u1eca. Ch\u1ec9 c\u1ea7n tr\xec 7 bi\u1ebfn h\u1eb1ng ng\xe0y, c\xf4ng \u0111\u1ee9c t\u1ea1o ra c\xf2n to l\u1edbn h\u01a1n c\u1ea3 vi\u1ec7c tr\xec t\u1ee5ng \u0111\u1ee7 108 bi\u1ebfn Ch\xfa \u0110\u1ea1i Bi tinh t\u1ea5n."],q,q),A.a4(["title","H\xe0ng Ph\u1ee5c Ma Qu\xe2n","meta",r,"preview","Ch\xfa L\u0103ng Nghi\xeam l\xe0 th\u1ea7n ch\xfa uy l\u1ef1c nh\u1ea5t \u0111\u1ec3 h\xe0ng ph\u1ee5c ma o\xe1n. Khi b\u1ea1n t\u1ee5ng Ch\xfa L\u0103ng Nghi\xeam, t\u1ea5t c\u1ea3 t\xe0 ma ngo\u1ea1i \u0111\u1ea1o, y\xeau ma qu\u1ef7 qu\xe1i \u0111\u1ec1u khi\u1ebfp s\u1ee3 v\xe0 kh\xf4ng d\xe1m \u0111\u1ebfn g\u1ea7n. \u0110\xf3 l\xe0 v\xec Ch\xfa L\u0103ng Nghi\xeam ph\xe1t ra h\xe0o quang r\u1ef1c r\u1ee1 c\u1ee7a Ph\u1eadt, soi s\xe1ng kh\u1eafp ph\xe1p gi\u1edbi."],q,q),A.a4(["title","V\u1ee5 Tr\u1ee9ng G\xe0","meta",r,"preview","\u201cB\u1ea1n cho r\u1eb1ng \u0103n chay th\xec \u0103n tr\u1ee9ng c\u0169ng \u0111\u01b0\u1ee3c? C\u0169ng \u0111\u01b0\u1ee3c! Ch\u1edd t\u1edbi khi b\u1ea1n \u0111\u1ea7u thai l\xe0m g\xe0 r\u1ed3i khi \u0111\xf3 b\u1ea1n s\u1ebd hi\u1ec3u (ph\u1eadn l\xe0m g\xe0) ch\xednh do \u0103n tr\u1ee9ng g\xe0 m\xe0 ra\u201d.\n\nH\u1ecfi: L\xe0 \u0111\u1ec7 t\u1eed Ph\u1eadt th\xec c\xf3 th\u1ec3 \u0103n tr\u1ee9ng kh\xf4ng?\n\u0110\xe1p: N\u1ebfu qu\xfd v\u1ecb th\xe8m mu\u1ed1n \u0103n nh\u1eefng th\u1ee9 dinh d\u01b0\u1ee1ng \u0111\xf3, th\xec c\u1ea7n g\xec ph\u1ea3i h\u1ecfi t\xf4i?\n\nH\u1ecfi: T\u1ea1i sao ng\u01b0\u1eddi \u0103n chay kh\xf4ng \u0111\u01b0\u1ee3c \u0103n tr\u1ee9ng?\n\u0110\xe1p: Kh\xf4ng c\xf3 g\xe0 tr\u1ed1ng, g\xe0 m\xe1i c\u0169ng c\xf3 th\u1ec3 \u1ea5p tr\u1ee9ng n\u1edf ra g\xe0 con nh\u01b0 th\u01b0\u1eddng. Ng\xe0y x\u01b0a ng\u01b0\u1eddi ta kh\xf4ng hi\u1ec3u \u0111i\u1ec1u n\xe0y n\xean h\u1ecd n\xf3i l\xe0, n\u1ebfu tr\u1ee9ng kh\xf4ng c\xf3 tr\u1ed1ng th\xec kh\xf4ng th\u1ec3 n\u1edf ra g\xe0 con. Nh\u01b0ng l\u1ed1i n\xf3i n\xe0y c\u0169ng kh\xf4ng \u0111\xfang s\u1ef1 th\u1eadt. B\u1edfi v\xec \u0111\u1ea1o l\xfd v\u1ed1n kh\xf4ng c\xf3 tuy\u1ec7t \u0111\u1ed1i, cho n\xean ch\xfang ta \u0103n chay quy\u1ebft kh\xf4ng n\xean \u0103n tr\u1ee9ng.\n\nH\u1ecfi: L\xfac \u0103n chay c\xf3 th\u1ec3 \u0103n tr\u1ee9ng g\xe0 kh\xf4ng?\n\u0110\xe1p: B\u1ea1n ch\u01b0a \u0103n \u0111\xe3 mu\u1ed1n bi\u1ebft! C\xf9ng v\u1edbi kh\xf4ng \u0103n th\xec th\u1ebf n\xe0o? \u0102n th\xec th\u1ebf n\xe0o?"],q,q),A.a4(["title","S\u1ef1 B\u1ea3o V\u1ec7 C\u1ee7a Ng\xe0n \u0110\xf3a Hoa Sen","meta",r,"preview",'Hai m\u01b0\u01a1i ch\xedn c\xe2u Ch\xfa \u0111\u1ea7u ti\xean, m\u1ed9t khi ni\u1ec7m ra th\xec s\u1ebd xu\u1ea5t hi\u1ec7n m\u1ed9t c\u1ea3nh gi\u1edbi l\xe0: b\u1ed1n m\u1eb7t t\xe1m ph\u01b0\u01a1ng c\xf3 r\u1ea5t nhi\u1ec1u hoa sen \u0111\u1ecf \u0111\u1ebfn \u1ee7ng h\u1ed9 ng\u01b0\u1eddi tr\xec Ch\xfa n\xe0y, cho n\xean n\xf3i: "Ng\xe0n \u0111\xf3a sen \u0111\u1ecf h\u1ed9 ng\u01b0\u1eddi tr\xec." (Thi\xean \u0111\xf3a h\u1ed3ng li\xean h\u1ed9 tr\u1ee5 th\xe2n). T\xe1m v\u1ea1n b\u1ed1n ng\xe0n Kim Cang t\u1ea1ng B\u1ed3 t\xe1t c\u0169ng \u0111\u1ebfn gia h\u1ed9 b\u1ea1n, cho n\xean n\xf3i: "Ng\u1ed3i tr\xean hoa sen \u0111i m\xe2y tr\u1eafng" (T\u1ecda li\xean phi th\u1eeba b\u1ea1ch v\xe2n \u0111\xf4n). C\xe2u Ch\xfa n\xe0y (Nam M\xf4 T\xe1t \u0110\xe1t Tha) v\u1ed1n d\u0129 b\u1ea3o h\u1ed9 ng\u01b0\u1eddi t\u1ee5ng, ai m\xe0 tr\xec c\xe2u Ch\xfa n\xe0y th\xec Ma v\u01b0\u01a1ng Ba Tu\u1ea7n kh\xf4ng c\xf3 c\xe1ch g\xec l\u1ea1i g\u1ea7n \u0111\u01b0\u1ee3c.'],q,q),A.a4(["title","T\u1ea1i Sao Ng\u01b0\u1eddi Ta Mu\u1ed1n T\u1ef1 S\xe1t?","meta",r,"preview","T\xf4i n\xf3i cho qu\xfd v\u1ecb bi\u1ebft, nh\u1eefng ng\u01b0\u1eddi t\u1ef1 s\xe1t \u0111a s\u1ed1 \u0111\u1ec1u b\u1ecb ma qu\u1ef7 k\xeau h\u1ecd \u0111\u1ebfn \u0111\xf3. Con qu\u1ef7 \u0111\xf3 \u0111\u1ed1i v\u1edbi ng\u01b0\u1eddi t\u1ef1 s\xe1t \u0111\xe3 ni\u1ec7m m\u1ed9t b\xe0i ch\xfa. Qu\u1ef7 ni\u1ec7m ch\xfa g\xec? N\xf3 n\xf3i: \u201cM\xe0y \u0111i ch\u1ebft \u0111i! M\xe0y \u0111i ch\u1ebft \u0111i! Ch\u1ebft \u0111i l\xe0 t\u1ed1t l\u1eafm! Ch\u1ebft \u0111i l\xe0 t\u1ed1t nh\u1ea5t \u0111\xf3!\u201d. Con qu\u1ef7 \u0111\xf3 c\xf3 tha t\xe2m th\xf4ng, n\xf3 l\u1ea5y qu\u1ef7 kh\xed x\xe2m nh\u1eadp v\xe0o t\xe2m c\u1ee7a ng\u01b0\u1eddi \u0111\xf3 khi\u1ebfn ng\u01b0\u1eddi \u0111\xf3 ngh\u0129 r\u1eb1ng: \u201cA! Ch\u1ebft \u0111i l\xe0 t\u1ed1t! Ch\u1ebft \u0111i l\xe0 t\u1ed1t!\u201d. Th\u1ebf l\xe0 ng\u01b0\u1eddi \u0111\xf3 b\xe8n \u0111i u\u1ed1ng thu\u1ed1c \u0111\u1ed9c t\u1ef1 t\u1eed, treo c\u1ed5, nh\u1ea3y xu\u1ed1ng bi\u1ec3n... V\xec v\u1eady b\u1ea5t c\u1ee9 l\xfac n\xe0o, m\u1ecdi ng\u01b0\u1eddi c\u1ea7n ph\u1ea3i ni\u1ec7m Ph\u1eadt, ni\u1ec7m ch\xfa. Qu\xfd v\u1ecb ni\u1ec7m Ph\u1eadt ni\u1ec7m ch\xfa th\xec l\xfac \u0111\xf3 c\xf3 Ph\u1eadt quang ph\u1ed5 chi\u1ebfu, ma qu\u1ef7 s\u1ebd b\u1ecf ch\u1ea1y \u0111i m\u1ea5t."],q,q),A.a4(["title","B\u1ed3 T\xe1t Kim Cang T\u1ea1ng \xc2m Th\u1ea7m Th\xfac Gi\u1ee5c","meta",r,"preview","Gi\u1ea3 s\u1eed t\xe2m ni\u1ec7m c\u1ee7a qu\xfd v\u1ecb v\xf4 c\xf9ng t\xe1n lo\u1ea1n, kh\xf4ng th\u1ec3 chuy\xean nh\u1ea5t, nh\u01b0ng n\u1ebfu mi\u1ec7ng c\u1ee7a qu\xfd v\u1ecb li\u1ec1n tr\xec t\u1ee5ng Ch\xfa L\u0103ng Nghi\xeam, th\xec B\u1ed3 T\xe1t Kim Cang T\u1ea1ng V\u01b0\u01a1ng li\u1ec1n d\xf9ng t\xe2m tinh ch\xe2n thu\u1ea7n th\u1ee5c \u0111i theo \xe2m th\u1ea7m th\xfac gi\u1ee5c. Ch\u1eef \u201c\xe2m th\u1ea7m th\xfac gi\u1ee5c\u201d n\xe0y v\xf4 c\xf9ng quan tr\u1ecdng, c\xf3 ngh\u0129a l\xe0 \u1edf ph\xeda sau \xe2m th\u1ea7m \u0111\u1ea9y b\u1ea1n m\u1ed9t c\xe1i, \xe2m th\u1ea7m h\u01b0\u1edbng d\u1eabn b\u1ea1n, nh\u1eafc nh\u1edf b\u1ea1n. Khi\u1ebfn t\xe2m t\xe1n lo\u1ea1n c\u1ee7a qu\xfd v\u1ecb d\u1ea7n m\u1ea5t \u0111i, m\u1ed9t ch\xfat, m\u1ed9t ch\xfat m\u1ed9t sinh ra \u0111\u1ecbnh l\u1ef1c, r\u1ed3i \u0111\u1ea1t \u0111\u01b0\u1ee3c \u0111\u1ecbnh l\u1ef1c, d\u1ea7n d\u1ea7n qu\xfd v\u1ecb s\u1ebd \u0111\u01b0\u1ee3c khai m\u1edf tr\xed hu\u1ec7."],q,q),A.a4(["title","Tr\xec Ch\xfa L\u0103ng Nghi\xeam Nh\u1ea5t T\xe2m","meta",r,"preview","Khi t\u1ee5ng Ch\xfa L\u0103ng Nghi\xeam kh\xf4ng n\xean c\xf3 t\xe2m mong c\u1ea7u, kh\xf4ng mong c\u1ea7u \u0111\u1eafc th\u1ea7n th\xf4ng, kh\xf4ng mong c\u1ea7u \u0111\u1eafc Ph\u1eadt nh\xe3n, kh\xf4ng mong c\u1ea7u ti\xeau tai, kh\xf4ng mong c\u1ea7u kh\u1ecfi b\u1ec7nh... Ch\u1ec9 c\u1ea7n nh\u1ea5t t\xe2m t\u1ee5ng tr\xec, th\xec c\xf4ng \u0111\u1ee9c m\u1edbi l\u1edbn. Gi\u1ed1ng nh\u01b0 \u0111\u1ee9a tr\u1ebb b\xfa m\u1eb9, ch\u1ec9 bi\u1ebft b\xfa th\xf4i ch\u1ee9 \u0111\xe2u c\xf3 ngh\u0129 g\xec kh\xe1c. B\xfa no r\u1ed3i th\xec ng\u1ee7, ng\u1ee7 d\u1eady l\u1ea1i b\xfa. Ng\u01b0\u1eddi t\u1ee5ng ch\xfa c\u0169ng ph\u1ea3i nh\u01b0 th\u1ebf, kh\xf4ng \u0111\u01b0\u1ee3c c\xf3 m\u1ed9t v\u1ecdng ni\u1ec7m n\xe0o xen v\xe0o."],q,q),A.a4(["title","Kh\xf4ng \u0102n Ng\u0169 V\u1ecb T\xe2n","meta",r,"preview","\u0110\u1ee9c Ph\u1eadt d\u1ea1y trong Kinh L\u0103ng Nghi\xeam: C\xe1c ch\xfang sinh c\u1ea7u qu\u1ea3 B\u1ed3 \u0110\u1ec1, c\u1ed1t y\u1ebfu l\xe0 kh\xf4ng \u0111\u01b0\u1ee3c \u0103n ng\u0169 v\u1ecb t\xe2n (h\xe0nh, t\u1ecfi, n\xe9n, h\u1eb9, h\u01b0ng h\xe0o). V\xec n\u0103m th\u1ee9 v\u1ecb cay n\xe0y, \u0103n ch\xedn th\xec ph\xe1t d\xe2m, \u0103n s\u1ed1ng th\xec th\xeam ph\u1eabn n\u1ed9. Nh\u1eefng ng\u01b0\u1eddi \u0103n n\u0103m th\u1ee9 v\u1ecb cay n\xe0y, tuy c\xf3 t\u1ee5ng tr\xec m\u01b0\u1eddi hai b\u1ed9 kinh Ph\u1eadt, m\u01b0\u1eddi ph\u01b0\u01a1ng Thi\xean ti\xean c\u0169ng \u0111\u1ec1u ch\xea m\xf9i h\xf4i th\u1ed1i m\xe0 tr\xe1nh xa. C\xe1c ng\u1ea1 qu\u1ef7 s\u1ebd th\u01b0\u1eddng li\u1ebfm m\xf4i mi\u1ec7ng c\u1ee7a ng\u01b0\u1eddi \u1ea5y, do lu\xf4n s\u1ed1ng chung v\u1edbi qu\u1ef7 n\xean ph\u01b0\u1edbc \u0111\u1ee9c ng\xe0y c\xe0ng ti\xeau m\xf2n, ch\u1eb3ng l\u1ee3i \xedch g\xec."],q,q),A.a4(["title","C\u1ea3nh Gi\u1edbi Nhi\u1ec7m M\xe0u","meta",s,"preview",'Khi ni\u1ec7m c\xe2u "Nam M\xf4 L\u0103ng Nghi\xeam H\u1ed9i Th\u01b0\u1ee3ng Ph\u1eadt B\u1ed3 T\xe1t" \u0111\u1ee7 ba l\u1ea7n, tr\xean h\u01b0 kh\xf4ng b\u1ed7ng hi\u1ec7n ra m\u1ed9t \u0110\xe0n th\xe0nh L\u0103ng Nghi\xeam r\u1ed9ng l\u1edbn \u0111\u1ebfn m\u1ee9c kh\xf4ng th\u1ea5y bi\xean gi\u1edbi. \u0110\xe0n th\xe0nh \u1ea5y nh\u01b0 m\u1ed9t c\xe1i \xf4 kh\u1ed5ng l\u1ed3 b\u1eb1ng \xe1nh s\xe1ng bao ph\u1ee7 t\u1eeb tr\xean kh\xf4ng trung xu\u1ed1ng. B\xean trong \u0110\xe0n th\xe0nh c\xf3 v\xf4 s\u1ed1 ch\u01b0 Ph\u1eadt, ch\u01b0 \u0110\u1ea1i B\u1ed3 T\xe1t c\xf9ng t\xe1m v\u1ea1n b\u1ed1n ng\xe0n Kim Cang T\u1ea1ng B\u1ed3 T\xe1t. T\u1ea5t c\u1ea3 c\xe1c Ng\xe0i \u0111\u1ec1u ph\xf3ng ra \u0111\u1ee7 th\u1ee9 h\xe0o quang v\xf4 c\xf9ng r\u1ef1c r\u1ee1 v\xe0 vi di\u1ec7u, chi\u1ebfu r\u1ecdi kh\u1eafp n\u01a1i v\xe0 gia tr\xec cho t\u1ea5t c\u1ea3 m\u1ecdi ng\u01b0\u1eddi. S\u1ef1 hi\u1ec7n di\u1ec7n v\xe0 \xe1nh s\xe1ng t\u1eeb \u0110\xe0n th\xe0nh kh\xf4ng ch\u1ec9 b\u1ea3o v\u1ec7 m\xe0 c\xf2n \u0111em l\u1ea1i l\u1ee3i \xedch l\u1edbn lao cho nh\u1eefng ai th\xe0nh t\xe2m tr\xec t\u1ee5ng, gi\xfap h\u1ecd ti\xeau tr\u1eeb nghi\u1ec7p ch\u01b0\u1edbng, t\xe2m tr\xed thanh t\u1ecbnh v\xe0 ng\xe0y c\xe0ng tinh t\u1ea5n tr\xean con \u0111\u01b0\u1eddng tu h\xe0nh.'],q,q),A.a4(["title","T\xe2m C\u1ee7a Ph\u1eadt - Th\xe2n C\u1ee7a Ph\u1eadt","meta",s,"preview","B\u1ea1ch \xe2n s\u01b0 Ph\u1ed5 Quang! Th\u1ea7n Ch\xfa L\u0103ng Nghi\xeam t\u1ea1i sao l\u1ea1i c\xf3 s\u1ee9c m\u1ea1nh l\u1edbn nh\u01b0 v\u1eady \u1ea1?\nHT. Ph\u1ed5 Quang: Th\u1ea7n Ch\xfa L\u0103ng Nghi\xeam n\xe0y l\xe0 ph\xe1p m\xf4n th\xf9 th\u1eafng nh\u1ea5t trong c\xe1c ph\xe1p m\xf4n. B\u1edfi v\xec n\xf3 ch\xednh l\xe0 t\xe2m c\u1ee7a Ph\u1eadt, l\xe0 th\xe2n c\u1ee7a Ph\u1eadt. Kh\xf4ng c\xf3 th\u1ea7n Ch\xfa L\u0103ng Nghi\xeam, th\xec kh\xf4ng c\xf3 t\u1ea5t c\u1ea3 ch\u01b0 Ph\u1eadt! ... Con ng\u01b0\u1eddi n\u1ebfu th\u1eadt s\u1ef1 hi\u1ec3u \u0111\u01b0\u1ee3c \u0111i\u1ec1u n\xe0y, th\xec \u0111\xe3 kh\xf4ng c\xf2n l\xe0 ph\xe0m phu n\u1eefa r\u1ed3i! Ni\u1ec7m \u0111\u1ee7 36.000 bi\u1ebfn, d\u01b0\u1edbi hai b\xe0n ch\xe2n c\u1ee7a con c\u0169ng c\xf3 hoa sen, khi con \u0111i \u0111\u1ee9ng, th\u1ef1c ra l\xe0 c\xf3 hoa sen n\xe2ng \u0111\u1ee1, ch\u1ec9 l\xe0 nh\u1ee5c nh\xe3n c\u1ee7a con nh\xecn kh\xf4ng th\u1ea5y m\xe0 th\xf4i."],q,q),A.a4(["title","C\u1ea3nh Gi\u1edbi \u0110\u1ea1i T\u1ef1 T\u1ea1i","meta",s,"preview",'C\xf3 c\xe2u: "L\xe0m ng\u01b0\u1eddi th\xec hi\u1ebfm khi kh\u1edd kh\u1ea1o", nh\u01b0ng tu h\xe0nh th\xec ph\u1ea3i \u0111\u1ea3o ng\u01b0\u1ee3c l\u1ea1i! Tu h\xe0nh l\xe0 ph\u1ea3i h\u1ecdc c\xe1ch kh\u1edd kh\u1ea1o... N\u1ebfu nh\u01b0 b\u1ea1n ch\u1eb3ng c\xf3 tr\xed tu\u1ec7, b\u1ea1n s\u1ebd ch\u1eb3ng th\u1ec3 kh\u1edd kh\u1ea1o \u0111\u01b0\u1ee3c. Gi\u1ed1ng nh\u01b0 B\u1ed3 T\xe1t B\u1ed1 \u0110\u1ea1i v\u1eady, Ng\xe0i kh\u1edd nh\u01b0ng m\xe0 Ng\xe0i l\u1ea1i s\u1ed1ng r\u1ea5t sung s\u01b0\u1edbng! S\u1ed1ng tr\xean \u0111\u1eddi \u0111\u1eebng bao gi\u1edd d\u1eb1n v\u1eb7t ng\u01b0\u1eddi kh\xe1c, c\u0169ng \u0111\u1eebng d\u1eb1n v\u1eb7t ch\xednh m\xecnh! Chuy\u1ec7n l\xfac t\xe1m gi\u1edd th\xec \u0111\u1ebfn ch\xedn gi\u1edd l\xe0 ph\u1ea3i qu\xean \u0111i r\u1ed3i. \u0110\u1ec3 nh\u1eefng chuy\u1ec7n phi\u1ec1n n\xe3o \u0111\xf3 trong l\xf2ng l\xe0m chi? Vi\u1ec7c g\xec \u0111\xe3 qua th\xec c\u1ee9 \u0111\u1ec3 n\xf3 qua \u0111i! \u0110\xf3 m\u1edbi l\xe0 Ph\u1eadt, B\u1ed3-t\xe1t, \u0111\xf3 m\u1edbi l\xe0 khai \u0111\u1ea1i ng\u1ed9! Cho n\xean ph\u1ea3i ni\u1ec7m Ch\xfa L\u0103ng Nghi\xeam, ni\u1ec7m Ch\xfa L\u0103ng Nghi\xeam m\u1edbi c\xf3 th\u1ec3 c\xf3 \u0111\u1ecbnh l\u1ef1c, m\u1edbi c\xf3 th\u1ec3 khai m\u1edf tr\xed tu\u1ec7, m\u1ed9t \u0111\u1eddi th\xe0nh Ph\u1eadt \u0111\u1ea1o.'],q,q),A.a4(["title","C\xf4ng \u0110\u1ee9c B\u1eb1ng 10 Toa T\xe0u H\u1ecfa Kinh \u0110\u1ea1i T\u1ea1ng","meta",s,"preview","Kinh \u0110\u1ea1i T\u1ea1ng nhi\u1ec1u nh\u01b0 v\u1eady, ni\u1ec7m t\u1edbi bao gi\u1edd m\u1edbi h\u1ebft? Nh\u01b0ng ni\u1ec7m m\u1ed9t bi\u1ebfn ch\xfa L\u0103ng Nghi\xeam th\xec c\xf4ng \u0111\u1ee9c b\u1eb1ng c\u1ea3 ni\u1ec7m 10 toa t\xe0u h\u1ecfa \u0111\u1ea7y \u1eafp kinh \u0110\u1ea1i T\u1ea1ng! Ai mu\u1ed1n t\u1ee5ng h\u1ebft b\u1ed9 kinh \u0110\u1ea1i T\u1ea1ng th\xec th\xe0 ni\u1ec7m m\u1ed9t bi\u1ebfn ch\xfa L\u0103ng Nghi\xeam c\xf2n h\u01a1n. C\xf3 ng\u01b0\u1eddi tu thi\u1ec1n, c\xf3 ng\u01b0\u1eddi ni\u1ec7m Ph\u1eadt, c\xf3 ng\u01b0\u1eddi tr\xec ch\xfa... c\xf3 t\u1edbi 8 v\u1ea1n 4 ng\xe0n ph\xe1p m\xf4n, nh\u01b0ng cho d\xf9 c\xf3 tu ph\xe1p n\xe0o \u0111i n\u1eefa, c\u0169ng ch\u1eb3ng b\u1eb1ng chuy\xean t\xe2m tu m\u1ed9t m\xecnh ch\xfa L\u0103ng Nghi\xeam. Cho n\xean, ai tu \u0111\u01b0\u1ee3c ch\xfa L\u0103ng Nghi\xeam, ng\u01b0\u1eddi \u0111\xf3 th\u1eadt s\u1ef1 l\xe0 c\xf3 \u0111\u1ea1i ph\xfac b\xe1o!"],q,q),A.a4(["title","Si\xeau \u0110\u1ed9 Cho Ng\u01b0\u1eddi \u0110\xe3 Khu\u1ea5t","meta",s,"preview","C\xf3 ng\u01b0\u1eddi h\u1ecfi v\u1ec1 c\xe1ch si\xeau \u0111\u1ed9 cho ng\u01b0\u1eddi th\xe2n \u0111\xe3 khu\u1ea5t. H\xf2a th\u01b0\u1ee3ng Ph\u1ed5 Quang \u0111\xe1p: Khi v\u1eeba ni\u1ec7m ch\xfa, b\u1ea1n ph\u1ea3i v\u1eeba qu\xe1n t\u01b0\u1edfng l\u1ea1i g\u01b0\u01a1ng m\u1eb7t v\u1edbi ng\u0169 quan \u0111ang m\u1ec9m c\u01b0\u1eddi l\xfac sinh ti\u1ec1n c\u1ee7a ng\u01b0\u1eddi ch\u1ebft. C\u1ee9 nh\u1ea5t t\xe2m ni\u1ec7m nh\u01b0 v\u1eady th\xec d\u01b0\u1edbi ch\xe2n th\u1ea7n th\u1ee9c c\u1ee7a ng\u01b0\u1eddi m\u1ea5t s\u1ebd l\u1eadp t\u1ee9c hi\u1ec7n ra m\u1ed9t \u0111\xf3a hoa sen, ng\u01b0\u1eddi m\u1ea5t t\u1ef1 nhi\xean s\u1ebd nh\u1eadn \u0111\u01b0\u1ee3c l\u1ee3i \xedch si\xeau tho\xe1t."],q,q),A.a4(["title","Ni\u1ec7m L\u0103ng Nghi\xeam Ch\xfa Nh\u01b0 \u0110i Thang M\xe1y","meta",s,"preview","M\u1ecdi ng\u01b0\u1eddi c\xf9ng nhau ni\u1ec7m L\u0103ng Nghi\xeam Ch\xfa th\xec th\u1ebf gi\u1edbi s\u1ebd b\xecnh y\xean, \u0111\u1ea5t n\u01b0\u1edbc s\u1ebd tai qua n\u1ea1n kh\u1ecfi.\n\nM\u1ed7i b\u1ed9 kinh chia ra r\u1ea5t nhi\u1ec1u ph\u1ea7n. \u0110\u1ecdc c\u1ea3 \u0111\u1eddi c\u0169ng kh\xf4ng h\u1ebft. Nh\u01b0ng L\u0103ng Nghi\xeam Ch\xfa \u0111\xe3 bao g\u1ed3m h\u1ebft t\u1ea5t c\u1ea3 kinh \u0111i\u1ec3n r\u1ed3i. Kinh T\xe2m Kinh ch\xednh l\xe0 ph\u1ea7n tinh t\xfay nh\u1ea5t c\u1ee7a t\u1ea5t c\u1ea3 kinh. L\xe0 \u0111\u1ec3 cho m\xecnh hi\u1ec3u v\xe0 ng\u1ed9 ra.\n\nNi\u1ec7m A Di \u0110\xe0 Ph\u1eadt th\xec tho\xe1t \u0111\u01b0\u1ee3c sinh t\u1eed, nh\u01b0ng ph\u1ea3i th\u1eadt nh\u1ea5t t\xe2m, t\xe2m ph\u1ea3i th\u1eadt s\u1ea1ch. Tham, s\xe2n, si, ki\xeau m\u1ea1n, nghi ng\u1edd... m\u1ed7i ch\u1eef l\xe0 m\u1ed9t c\u1ea3nh. S\u1ebd \u0111\u1ecda v\xe0o \u0111\u01b0\u1eddng A Tu La, \u0111\u01b0\u1eddng ng\u1ea1 qu\u1ef7... r\u01a1i v\xe0o \u0111\u01b0\u1eddng n\xe0o th\xec theo \u0111\u01b0\u1eddng \u0111\xf3.\n\nNi\u1ec7m \u0110\u1ea1i Bi Ch\xfa 108 l\u1ea7n c\u0169ng kh\xf4ng b\u1eb1ng ni\u1ec7m 1 l\u1ea7n L\u0103ng Nghi\xeam Ch\xfa. Kh\xf4ng b\u1eb1ng ni\u1ec7m 7 l\u1ea7n Ng\u0169 \u0110\u1ea1i T\xe2m Ch\xfa. \u0110\u1ea1i Bi Ch\xfa l\xe0 \u0111\u1ec3 c\u1ee9u kh\u1ed5. Ni\u1ec7m \u0111\u1ebfn m\u1ee9c cao nh\u1ea5t th\xec to\xe0n th\xe2n s\xe1ng l\xean, c\xf3 th\u1ec3 th\xe0nh B\u1ed3 T\xe1t, nh\u01b0ng v\u1eabn ch\u01b0a th\xe0nh Ph\u1eadt \u0111\u01b0\u1ee3c. Mu\u1ed1n th\xe0nh Ph\u1eadt th\xec ph\u1ea3i ni\u1ec7m L\u0103ng Nghi\xeam Ch\xfa n\xe0y.\n\nNi\u1ec7m kinh kh\xe1c th\xec ph\u1ea3i h\u1ed3i h\u01b0\u1edbng. Nh\u01b0ng ni\u1ec7m L\u0103ng Nghi\xeam Ch\xfa n\xe0y v\xe0 Kinh Kim Cang th\xec kh\xf4ng c\u1ea7n h\u1ed3i h\u01b0\u1edbng. \u0110\u1ee9c Ph\u1eadt \u0111\xe3 \u1ea5n ch\u1ee9ng r\u1ed3i. Kh\xf4ng c\u1ea7n ph\u1ea3i l\xe0m th\xeam n\u1eefa. Ni\u1ec7m L\u0103ng Nghi\xeam Ch\xfa, m\u1ed9t \u0111\u1eddi n\xe0y l\xe0 th\xe0nh Ph\u1eadt.\n\nNi\u1ec7m L\u0103ng Nghi\xeam Ch\xfa gi\u1ed1ng nh\u01b0 \u0111i thang m\xe1y v\u1eady \u0111\xf3. V\xc8O m\u1ed9t c\xe1i l\xe0 th\xe0nh Ph\u1eadt r\u1ed3i!"],q,q),A.a4(["title","\u0110\u1ed9ng T\u1eeb Bi","meta",s,"preview","\u0110\u1ed9ng T\u1eeb Bi, t\u1eeb x\u01b0a \u0111\u1ebfn nay kh\xf4ng bi\u1ebft \u0111\xe3 c\xf3 bao nhi\xeau v\u1ecb \u0111\u1ea1i \u0111\u1ee9c (b\u1eadc tu h\xe0nh cao th\xe2m) \u0111\u1ebfn \u0111\xe2y \u0111\xf3ng c\u1eeda \u1ea9n tu r\u1ed3i. S\u01b0 ph\u1ee5 l\xe0 h\xf2a th\u01b0\u1ee3ng Ph\u1ed5 Quang k\u1ec3 l\u1ea1i r\u1eb1ng, nh\u1eefng gi\u1ecdt n\u01b0\u1edbc r\u1ec9 ra t\u1eeb khe \u0111\xe1 trong \u0111\u1ed9ng ch\xednh l\xe0 n\u01b0\u1edbc m\u1eaft c\u1ee7a Ph\u1eadt B\u1ed3 T\xe1t. N\u01b0\u1edbc n\xe0y c\xf3 th\u1ec3 u\u1ed1ng ch\u1ee9 kh\xf4ng \u0111\u01b0\u1ee3c l\xe3ng ph\xed, v\xe0 c\xf2n ch\u1eefa \u0111\u01b0\u1ee3c b\xe1ch b\u1ec7nh. C\u0103n nh\xe0 \u0111\xe1 nh\u1ecf nh\u1eafn, gi\u1ea3n d\u1ecb kia ch\xednh l\xe0 n\u01a1i h\xf2a th\u01b0\u1ee3ng Ph\u1ed5 Quang t\u1eebng tu h\xe0nh l\xfac c\xf2n tr\u1ebb. Th\u1eddi D\xe2n Qu\u1ed1c, c\xe1c v\u1ecb h\xf2a th\u01b0\u1ee3ng n\u1ed5i ti\u1ebfng nh\u01b0 ng\xe0i H\u01b0 V\xe2n, ph\xe1p s\u01b0 Vi\xean Anh, v\xe0 h\xf2a th\u01b0\u1ee3ng Lai Qu\u1ea3 c\u0169ng \u0111\u1ec1u t\u1eebng tu h\xe0nh \u1edf n\u01a1i n\xe0y."],q,q)],t.m0),new A.at6(this),p),p.i("y.E"))
